<script setup lang="ts">import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'; import * as echarts from 'echarts'; import type { RegisterTrend } from '@/types/domain'; const props = defineProps<{ data?: RegisterTrend }>(); const el = ref<HTMLElement>(); let chart: echarts.ECharts | undefined; function render() { if (!el.value) return; chart ??= echarts.init(el.value); chart.setOption({ grid: { left: 30, right: 18, top: 22, bottom: 24 }, tooltip: { trigger: 'axis' }, xAxis: { type: 'category', boundaryGap: false, data: props.data?.months || [] }, yAxis: { type: 'value', splitLine: { lineStyle: { color: '#edf4f2' } } }, series: [{ type: 'line', smooth: true, data: props.data?.counts || [], symbol: 'circle', symbolSize: 7, itemStyle: { color: '#ed775c' }, lineStyle: { width: 3, color: '#ed775c' }, areaStyle: { color: 'rgba(237,119,92,.10)' } }] }); } onMounted(() => nextTick(render)); watch(() => props.data, render, { deep: true }); onBeforeUnmount(() => chart?.dispose())</script>
<template><div ref="el" class="chart chart--trend"></div></template>
